// 제네릭 우선순위 큐 추상 기본 클래스
public abstract class PriorityQueue<T>
{
    [DllImport("C++DLL", CallingConvention = CallingConvention.Cdecl)]
    protected static extern IntPtr CreatePriorityQueue();

    [DllImport("C++DLL", CallingConvention = CallingConvention.Cdecl)]
    protected static extern void DestroyPriorityQueue(IntPtr queue);

    protected IntPtr queuePtr;

    public PriorityQueue()
    {
        queuePtr = CreatePriorityQueue();
    }

    ~PriorityQueue()
    {
        if (queuePtr != IntPtr.Zero)
        {
            DestroyPriorityQueue(queuePtr);
        }
    }

    // 팩토리 메서드로 타입별 구현체 생성
    public static PriorityQueue<T> Create()
    {
        if (typeof(T) == typeof(int))
            return new IntPriorityQueue() as PriorityQueue<T>;
        else if (typeof(T) == typeof(float))
            return new FloatPriorityQueue() as PriorityQueue<T>;
        else if (typeof(T) == typeof(double))
            return new DoublePriorityQueue() as PriorityQueue<T>;

        throw new NotSupportedException($"Type {typeof(T)} is not supported");
    }

    public abstract void Push(T item, int priority);
    public abstract T Pop();
}

