// 실제 PMove.cs 코드 - 플레이어 피해 처리 시스템
public partial class PMove
{
    // 플레이어 피해 처리 메서드
    public void Damaged()
    {
        if (canDamaged)
        {
            canDamaged = false;

            State playerState = GameManager.info.allPlayerState;

            // 쉴드가 있을 경우 쉴드부터 차감
            if (GameManager.info.currentShield > 0)
            {
                GameManager.info.currentShield -= attackerDamage;
                if (GameManager.info.currentShield < 0)
                {
                    // 쉴드가 0 미만이 되면 체력에서 차감
                    playerState.currentHp += GameManager.info.currentShield;
                    GameManager.info.currentShield = 0;
                }
            }
            else
            {
                // 방어력 적용한 데미지 계산
                int finalDamage = Mathf.Max(1, attackerDamage - playerState.defense);
                playerState.currentHp -= finalDamage;
            }

            // 체력바 UI 업데이트
            BossHp.UpdatePlayerHP();

            // 체력이 0 이하가 되면 사망 처리
            if (playerState.currentHp <= 0)
            {
                playerState.currentHp = 0;

                // "Craving" 능력이 있으면 부활
                if (GameManager.info.Craving > 0)
                {
                    playerState.currentHp = playerState.maxHP;
                    GameManager.info.Craving--;
                }
                else
                {
                    // 사망 처리
                    Die();
                }
            }

            StartCoroutine(DamagedDelay());
        }
    }

    // 10초마다 쉴드 자동 충전
    public void RefillShield()
    {
        int refillAmount = Mathf.RoundToInt(GameManager.info.maxShield * 0.1f);
        GameManager.info.currentShield = Mathf.Min(GameManager.info.maxShield, 
                                                  GameManager.info.currentShield + refillAmount);

        // 체력바 UI 업데이트
        BossHp.UpdatePlayerHP();
    }

    private IEnumerator DamagedDelay()
    {
        yield return new WaitForSeconds(0.5f);
        canDamaged = true;
    }
}

// 실제 BossController.cs 코드 - 보스 피해 처리
public class BossController : MonoBehaviour
{
    public void Damaged()
    {
        if (canDamaged)
        {
            canDamaged = false;

            MonsterState bossState = GetComponent<MonsterController>().monsterState;

            // 방어력 적용한 데미지 계산
            int playerDamage = GameManager.info.allPlayerState.damage;
            int finalDamage = Mathf.Max(1, playerDamage - bossState.defense);

            bossState.currentHp -= finalDamage;

            // 보스 체력바 UI 업데이트
            BossHp.BossSliderReset();

            // 출혈 효과 적용
            if (GameManager.info.bleeding > 0)
            {
                StartCoroutine(BleedingCoroutine());
            }

            if (bossState.currentHp <= 0)
            {
                bossState.currentHp = 0;
                Die();
            }

            StartCoroutine(DamagedDelay());
        }
    }

    private IEnumerator BleedingCoroutine()
    {
        MonsterState bossState = GetComponent<MonsterController>().monsterState;

        for (int i = 0; i < 5; i++) // 5초간 지속
        {
            yield return new WaitForSeconds(1f);

            if (bossState.currentHp > 0)
            {
                bossState.currentHp -= GameManager.info.bleeding;
                BossHp.BossSliderReset();

                if (bossState.currentHp <= 0)
                {
                    bossState.currentHp = 0;
                    Die();
                    break;
                }
            }
        }
    }

    private void Die()
    {
        // 보스 사망 처리
        MonsterState bossState = GetComponent<MonsterController>().monsterState;

        // 골드 드롭
        BossHPManager bossHPManager = FindObjectOfType<BossHPManager>();
        if (bossHPManager != null)
        {
            bossHPManager.Drap(bossState.Money);
        }

        Destroy(gameObject);
    }

    private IEnumerator DamagedDelay()
    {
        yield return new WaitForSeconds(0.1f);
        canDamaged = true;
    }
}

