public class DecodeString : MonoBehaviour
{
    [DllImport("C++DLL", CallingConvention = CallingConvention.Cdecl)]
    private static extern IntPtr DecodeStringMain(string input);

    // 호출자 검증을 통한 보안 문자열 디코딩
    public static string DecodeSecureString(string encryptedString)
    {
        // StackTrace를 사용하여 호출자 클래스 검증
        StackTrace stackTrace = new StackTrace();
        StackFrame[] frames = stackTrace.GetFrames();

        bool isAuthorized = false;
        foreach (StackFrame frame in frames)
        {
            string className = frame.GetMethod().DeclaringType?.Name;

            // 승인된 클래스만 디코딩 허용
            if (className == "MultiPlay" || className == "Login")
            {
                isAuthorized = true;
                break;
            }
        }

        if (!isAuthorized)
        {
            throw new UnauthorizedAccessException("Unauthorized access to secure string");
        }

        // C++ DLL을 통한 실제 디코딩
        IntPtr result = DecodeStringMain(encryptedString);
        string decodedString = Marshal.PtrToStringAnsi(result);

        // 네이티브 메모리 해제
        Marshal.FreeHGlobal(result);

        return decodedString;
    }
}

