using System;

// 실제 EquipmentState.cs 코드
// 플레이어가 장착할 수 있는 장비 타입
[Flags]
public enum EquipmentState : uint
{
    EQUIPMENT_ALL = 0xFFFFFFFF, // 모든 장비
    EQUIPMENT_WEAPON_ONEHANDED_SHORT_RANGE = 0xF0000000, // 한손 단거리 무기
    EQUIPMENT_WEAPON_ONEHANDED_LARGE_RANGE = 0x0F000000, // 한손 장거리 무기
    EQUIPMENT_WEAPON_TWOHANDED_SHORT_RANGE = 0x00F00000, // 양손 무기
    EQUIPMENT_WEAPON_TWOHANDED_LARGE_RANGE = 0x000F0000, // 양손 무기
    EQUIPMENT_ACCESSORY = 0x0000F000 // 악세서리
}

// 사용 예시
public class EquipmentManager
{
    private EquipmentState currentEquipment = 0;

    // 장비 착용
    public void EquipItem(EquipmentState equipment)
    {
        currentEquipment |= equipment; // OR 연산으로 플래그 설정
    }

    // 장비 해제
    public void UnequipItem(EquipmentState equipment)
    {
        currentEquipment &= ~equipment; // AND NOT 연산으로 플래그 제거
    }

    // 특정 장비 착용 여부 확인
    public bool IsEquipped(EquipmentState equipment)
    {
        return (currentEquipment & equipment) != 0;
    }

    // 모든 장비 착용 확인
    public bool HasAllEquipment()
    {
        return (currentEquipment & EquipmentState.EQUIPMENT_ALL) == EquipmentState.EQUIPMENT_ALL;
    }
}

