using System.Collections;
using System.Collections.Generic;

// DashBarUI.cs - 대쉬 바 UI 관리 시스템
public class DashBarUI : MonoBehaviour
{
    [Header("대쉬 바 설정")]
    [SerializeField] private GameObject dashBarPrefab; // 대쉬 바 프리팹
    [SerializeField] private Transform dashBarContainer; // 대쉬 바 컨테이너
    [SerializeField] private Color availableColor = Color.cyan; // 사용 가능한 대쉬 색상
    [SerializeField] private Color unavailableColor = Color.gray; // 사용 불가능한 대쉬 색상
    [SerializeField] private Color cooldownColor = Color.yellow; // 쿨다운 중인 대쉬 색상

    [Header("애니메이션 설정")]
    [SerializeField] private float fillSpeed = 2f; // 대쉬 바 회복 애니메이션 속도
    [SerializeField] private AnimationCurve dashUseCurve = AnimationCurve.EaseInOut(0, 1, 1, 0); // 대쉬 사용 애니메이션 곡선
    [SerializeField] private float usageAnimationDuration = 0.3f; // 사용 애니메이션 지속시간

    private State playerState;
    private List<DashBar> dashBars = new List<DashBar>();
    private int currentDashCount;
    private float[] dashCooldowns; // 각 대쉬 바의 쿨다운 시간

    [System.Serializable]
    private class DashBar
    {
        public GameObject barObject;
        public Slider fillSlider;
        public Image fillImage;
        public bool isAvailable;
        public float cooldownTime;

        public DashBar(GameObject obj)
        {
            barObject = obj;
            fillSlider = obj.GetComponent<Slider>();
            fillImage = fillSlider.fillRect.GetComponent<Image>();
            isAvailable = true;
            cooldownTime = 0f;
        }
    }

    private void Start()
    {
        playerState = Resources.Load<State>("Scriptable/Player");
        Debug.Assert(playerState != null, "플레이어 상태가 없습니다.");

        InitializeDashBars();
    }

    private void InitializeDashBars()
    {
        // 기존 대쉬 바 제거
        foreach (Transform child in dashBarContainer)
        {
            Destroy(child.gameObject);
        }
        dashBars.Clear();

        // 플레이어 상태에서 대쉬 바 개수 가져오기
        int dashBarCount = playerState.dashBarCount;
        currentDashCount = dashBarCount;
        dashCooldowns = new float[dashBarCount];

        // 대쉬 바 생성
        for (int i = 0; i < dashBarCount; i++)
        {
            GameObject dashBarObj = Instantiate(dashBarPrefab, dashBarContainer);
            DashBar dashBar = new DashBar(dashBarObj);

            // 초기 상태 설정
            dashBar.fillSlider.value = 1f;
            dashBar.fillImage.color = availableColor;
            dashBar.isAvailable = true;

            dashBars.Add(dashBar);
            dashCooldowns[i] = 0f;
        }
    }

    private void Update()
    {
        // 대쉬 바 개수가 변경된 경우 재초기화
        if (currentDashCount != playerState.dashBarCount)
        {
            InitializeDashBars();
        }

        UpdateDashBars();
    }

    private void UpdateDashBars()
    {
        for (int i = 0; i < dashBars.Count; i++)
        {
            DashBar dashBar = dashBars[i];

            // 쿨다운 업데이트
            if (!dashBar.isAvailable)
            {
                dashCooldowns[i] -= Time.deltaTime;

                if (dashCooldowns[i] <= 0f)
                {
                    // 쿨다운 완료 - 대쉬 바 회복 시작
                    dashBar.isAvailable = true;
                    dashBar.cooldownTime = 0f;
                    StartCoroutine(RestoreDashBar(i));
                }
                else
                {
                    // 쿨다운 진행 중
                    float maxCooldown = GetDashCooldown();
                    float progress = 1f - (dashCooldowns[i] / maxCooldown);
                    dashBar.fillSlider.value = progress;
                    dashBar.fillImage.color = cooldownColor;
                }
            }
        }
    }

    // 대쉬 사용 시 호출되는 메서드
    public bool UseDash()
    {
        // 사용 가능한 대쉬 바 찾기
        for (int i = 0; i < dashBars.Count; i++)
        {
            if (dashBars[i].isAvailable && dashBars[i].fillSlider.value >= 1f)
            {
                StartCoroutine(UseDashBar(i));
                return true;
            }
        }

        return false; // 사용 가능한 대쉬 바가 없음
    }

    private IEnumerator UseDashBar(int index)
    {
        DashBar dashBar = dashBars[index];
        dashBar.isAvailable = false;

        // 대쉬 사용 애니메이션
        float elapsedTime = 0f;

        while (elapsedTime < usageAnimationDuration)
        {
            elapsedTime += Time.deltaTime;
            float progress = elapsedTime / usageAnimationDuration;
            float curveValue = dashUseCurve.Evaluate(progress);

            dashBar.fillSlider.value = curveValue;
            dashBar.fillImage.color = Color.Lerp(availableColor, unavailableColor, progress);

            yield return null;
        }

        // 대쉬 바 완전 소모
        dashBar.fillSlider.value = 0f;
        dashBar.fillImage.color = unavailableColor;

        // 쿨다운 시작
        dashCooldowns[index] = GetDashCooldown();
    }

    private IEnumerator RestoreDashBar(int index)
    {
        DashBar dashBar = dashBars[index];

        float elapsedTime = 0f;
        float duration = 1f / fillSpeed;

        while (elapsedTime < duration)
        {
            elapsedTime += Time.deltaTime;
            float progress = elapsedTime / duration;

            dashBar.fillSlider.value = Mathf.Lerp(0f, 1f, progress);
            dashBar.fillImage.color = Color.Lerp(cooldownColor, availableColor, progress);

            yield return null;
        }

        // 대쉬 바 완전 회복
        dashBar.fillSlider.value = 1f;
        dashBar.fillImage.color = availableColor;
    }

    private float GetDashCooldown()
    {
        // 플레이어 상태에서 대쉬 쿨다운 시간 가져오기 (예: 2초)
        return playerState.reloadTime > 0 ? playerState.reloadTime : 2f;
    }

    // 현재 사용 가능한 대쉬 개수 반환
    public int GetAvailableDashCount()
    {
        int count = 0;
        foreach (DashBar dashBar in dashBars)
        {
            if (dashBar.isAvailable && dashBar.fillSlider.value >= 1f)
                count++;
        }
        return count;
    }

    // 모든 대쉬 바 회복 (특정 아이템 사용 시 등)
    public void RestoreAllDashBars()
    {
        for (int i = 0; i < dashBars.Count; i++)
        {
            dashBars[i].isAvailable = true;
            dashBars[i].fillSlider.value = 1f;
            dashBars[i].fillImage.color = availableColor;
            dashCooldowns[i] = 0f;
        }
    }
}

