// 실제 ResultUI.cs 코드 - 게임 결과 및 씬 전환 관리
public class ResultUI : MonoBehaviour
{
    [SerializeField] private GameObject resultUI; // 결과 UI
    [SerializeField] private TextMeshProUGUI playTimeText; // 플레이 시간 텍스트
    [SerializeField] private TextMeshProUGUI stageText; // 현재 스테이지 텍스트
    [SerializeField] private Slider expSlider; // 경험치 슬라이더
    [SerializeField] private FadeEffect fade; // 페이드 효과

    public static List<GameObject> addItemList = new List<GameObject>(); // 획득 아이템 목록
    public static List<GameObject> getItemList = new List<GameObject>(); // 표시할 아이템 목록
    private static float playTime = 0f; // 플레이 시간
    private static int getGold = 0; // 획득 골드
    private static float getEXP = 0f; // 획득 경험치

    // 게임 종료 시 결과 화면 표시
    public void GameIsEnd()
    {
        resultUI.SetActive(true);

        // 플레이 시간 표시
        ShowPlayTime();

        // 현재 스테이지 표시
        string currentStage = SceneManager.GetActiveScene().name;
        stageText.text = $"스테이지: {currentStage}";

        // 경험치 및 레벨 처리
        StartCoroutine(ResultEXP());

        // 획득 아이템 표시
        ShowItemList();

        // 커서 활성화
        Cursor.lockState = CursorLockMode.None;
        Cursor.visible = true;
    }

    // 경험치 획득 추적
    public static void GetEXP(float exp)
    {
        getEXP += exp;
    }

    // 골드 획득 추적
    public static void GetGold(int gold)
    {
        getGold += gold;
    }

    // 아이템 획득 추적
    public static void GetItem(GameObject item)
    {
        addItemList.Add(item);
    }

    // 플레이 시간 표시
    private void ShowPlayTime()
    {
        int minutes = Mathf.FloorToInt(playTime / 60f);
        int seconds = Mathf.FloorToInt(playTime % 60f);
        playTimeText.text = $"탐험 시간: {minutes:00}:{seconds:00}";
    }

    // 경험치 처리 및 레벨업
    private IEnumerator ResultEXP()
    {
        State playerState = Resources.Load<State>("Scriptable/Player");

        // 경험치 적용
        float targetExp = playerState.currentExp + getEXP;

        while (playerState.currentExp < targetExp)
        {
            playerState.currentExp += Time.deltaTime * 50f;

            // 레벨업 체크
            if (playerState.currentExp >= 100f)
            {
                playerState.level++;
                playerState.currentExp -= 100f;
                targetExp -= 100f;
            }

            // 슬라이더 업데이트
            expSlider.value = playerState.currentExp / 100f;
            yield return null;
        }
    }

    // 마을로 돌아가기 (씬 전환)
    public void OnRestartButtonClick()
    {
        StartCoroutine(ReStart());
    }

    private IEnumerator ReStart()
    {
        resultUI.SetActive(false);
        StartCoroutine(fade.FadeOut());

        // 페이드 완료 대기
        while (fade.isFadeOut)
            yield return null;

        // 게임 상태 초기화
        addItemList.Clear();
        getItemList.Clear();
        Inventory.inventorySlotItem = null;

        playTime = 0f;
        getGold = 0;
        getEXP = 0f;

        // 기존 오브젝트 정리
        GameObject eventSystem = GameObject.Find("EventSystemDonDestory");
        if (eventSystem != null)
            eventSystem.GetComponent<UINotDestroyOpen>().DestroyThis();

        GameObject player = GameObject.FindGameObjectWithTag("Player");
        if (player != null)
            Destroy(player);

        GameObject gameManager = GameObject.Find("GameManager");
        if (gameManager != null)
            Destroy(gameManager);

        // 맵 씬으로 전환
        SceneManager.LoadScene("Map");
    }

    private void Update()
    {
        // 플레이 시간 추적
        if (!resultUI.activeSelf)
        {
            playTime += Time.deltaTime;
        }
    }
}

