public class UIOpen : MonoBehaviour
{
    [Header("UI 제어")]
    public GameObject targetUI;
    public AnimationCurve openCurve = AnimationCurve.EaseInOut(0, 0, 1, 1);
    public float animationDuration = 0.3f;

    private bool isAnimating = false;

    public void OpenUI()
    {
        if (isAnimating || targetUI.activeInHierarchy) return;

        StartCoroutine(AnimateUI(true));
    }

    public void CloseUI()
    {
        if (isAnimating || !targetUI.activeInHierarchy) return;

        StartCoroutine(AnimateUI(false));
    }

    private IEnumerator AnimateUI(bool opening)
    {
        isAnimating = true;

        if (opening)
        {
            targetUI.SetActive(true);
            targetUI.transform.localScale = Vector3.zero;
        }

        float elapsedTime = 0f;
        Vector3 startScale = opening ? Vector3.zero : Vector3.one;
        Vector3 endScale = opening ? Vector3.one : Vector3.zero;

        while (elapsedTime < animationDuration)
        {
            elapsedTime += Time.deltaTime;
            float progress = elapsedTime / animationDuration;
            float curveValue = openCurve.Evaluate(progress);

            targetUI.transform.localScale = Vector3.Lerp(startScale, endScale, curveValue);
            yield return null;
        }

        targetUI.transform.localScale = endScale;

        if (!opening)
        {
            targetUI.SetActive(false);
        }

        isAnimating = false;
    }
}

