    {
        Debug.Assert(camera != null, "미니맵 출력 카메라가 존재하지 않습니다.");

        cameraCompo = camera.GetComponent<Camera>();
        Debug.Assert(cameraCompo != null, "카메라 컴포넌트가 존재하지 않습니다.");

        multiple.text = (20 / cameraCompo.orthographicSize).ToString("X#0.#");

