// 로그인 및 인증 관리
public class Login : MonoBehaviour
{
    [Header("로그인 UI")]
    public InputField usernameInput;
    public InputField passwordInput;
    public Button loginButton;
    public Text statusText;

    [Header("서버 설정")]
    public string serverUrl = "http://localhost:8080";
    public float connectionTimeout = 10f;

    private bool isLoggingIn = false;
    public static bool isLoggedIn = false;
    public static string currentUsername = "";

    private void Start()
    {
        InitializeLoginUI();
    }

    private void InitializeLoginUI()
    {
        loginButton.onClick.AddListener(OnLoginButtonClick);

        // Enter 키로 로그인 처리
        usernameInput.onEndEdit.AddListener(delegate { 
            if (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter))
                OnLoginButtonClick();
        });

        passwordInput.onEndEdit.AddListener(delegate { 
            if (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter))
                OnLoginButtonClick();
        });

        UpdateStatusText("사용자명과 비밀번호를 입력하세요.");
    }

    public void OnLoginButtonClick()
    {
        if (isLoggingIn) return;

        string username = usernameInput.text.Trim();
        string password = passwordInput.text;

        if (ValidateInput(username, password))
        {
            StartCoroutine(LoginProcess(username, password));
        }
    }

    private bool ValidateInput(string username, string password)
    {
        if (string.IsNullOrEmpty(username))
        {
            UpdateStatusText("사용자명을 입력하세요.");
            return false;
        }

        if (string.IsNullOrEmpty(password))
        {
            UpdateStatusText("비밀번호를 입력하세요.");
            return false;
        }

        if (username.Length < 3)
        {
            UpdateStatusText("사용자명은 3자 이상이어야 합니다.");
            return false;
        }

        return true;
    }

    private IEnumerator LoginProcess(string username, string password)
    {
        isLoggingIn = true;
        UpdateStatusText("로그인 중...");
        loginButton.interactable = false;

        // 로그인 요청 데이터 준비
        LoginRequest loginData = new LoginRequest
        {
            username = username,
            password = password,
            clientVersion = Application.version
        };

        string jsonData = JsonUtility.ToJson(loginData);

        using (UnityWebRequest www = UnityWebRequest.Post(serverUrl + "/api/login", jsonData, "application/json"))
        {
            www.timeout = (int)connectionTimeout;

            yield return www.SendWebRequest();

            if (www.result == UnityWebRequest.Result.Success)
            {
                try
                {
                    LoginResponse response = JsonUtility.FromJson<LoginResponse>(www.downloadHandler.text);

                    if (response.success)
                    {
                        // 로그인 성공
                        isLoggedIn = true;
                        currentUsername = username;
                        UpdateStatusText("로그인 성공!");

                        // 게임 씬으로 전환
                        yield return new WaitForSeconds(1f);
                        SceneManager.LoadScene("GameScene");
                    }
                    else
                    {
                        UpdateStatusText("로그인 실패: " + response.message);
                    }
                }
                catch (System.Exception e)
                {
                    UpdateStatusText("서버 응답 처리 오류: " + e.Message);
                }
            }
            else
            {
                UpdateStatusText("네트워크 오류: " + www.error);
            }
        }

        isLoggingIn = false;
        loginButton.interactable = true;
    }

    private void UpdateStatusText(string message)
    {
        if (statusText != null)
        {
            statusText.text = message;
        }
    }

    public static void GameLogin()
    {
        // 전역 로그인 상태 초기화
        isLoggedIn = false;
        currentUsername = "";
    }
}

[System.Serializable]
public class LoginRequest
{
    public string username;
    public string password;
    public string clientVersion;
}

[System.Serializable]
public class LoginResponse
{
    public bool success;
    public string message;
    public string token;
}

