using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

// 실제 EquidStore.cs 코드 - 상점 메인 시스템
public class EquidStore : MonoBehaviour
{
    [SerializeField] private GameObject[] itemSlots; // 상점 아이템 슬롯들
    [SerializeField] private TextMeshProUGUI itemName; // 선택된 아이템 이름
    [SerializeField] private TextMeshProUGUI itemDescription; // 선택된 아이템 설명
    [SerializeField] private TextMeshProUGUI itemPrice; // 선택된 아이템 가격
    [SerializeField] private Button buyButton; // 구매 버튼
    [SerializeField] private Image selectedItemImage; // 선택된 아이템 이미지

    private static SelectableItem selectedItem; // 현재 선택된 아이템
    private static EquidLevel excludeLevel = EquidLevel.legend; // 상점에서 제외할 등급

    private void Start()
    {
        ItemUpdate(); // 상점 슬롯에 랜덤 아이템 배치

        // 구매 버튼 이벤트 등록
        buyButton.onClick.AddListener(() => {
            if (selectedItem != null)
            {
                BuyEffect();
            }
        });
    }

    // 상점 슬롯에 랜덤 아이템 생성
    private void ItemUpdate()
    {
        for (int i = 0; i < itemSlots.Length; i++)
        {
            SelectedRandomItem(i);
        }
    }

    // 특정 슬롯에 랜덤 아이템 배치
    private void SelectedRandomItem(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= itemSlots.Length) return;

        GameObject slot = itemSlots[slotIndex];
        EquidStoreItem storeItem = slot.GetComponent<EquidStoreItem>();

        if (storeItem != null)
        {
            // ItemSelector를 통해 랜덤 아이템 선택 (전설 등급 제외)
            SelectableItem randomItem = ItemSelector.GetRandomItem(excludeLevel);
            storeItem.SetItem(randomItem);
        }
    }

    // 아이템 선택 시 상세 정보 표시
    public static void OnSelectedItem(SelectableItem item)
    {
        selectedItem = item;

        EquidStore store = FindObjectOfType<EquidStore>();
        if (store != null && selectedItem != null)
        {
            // 타이핑 효과로 아이템 정보 표시
            store.StartCoroutine(store.TypeWriter(selectedItem.itemName, store.itemName));
            store.StartCoroutine(store.TypeWriter(selectedItem.description, store.itemDescription));
            store.itemPrice.text = selectedItem.price.ToString("#,##0") + "G";
            store.selectedItemImage.sprite = selectedItem.itemIcon;

            // 구매 가능 여부 확인
            State playerState = GameManager.info.allPlayerState;
            store.buyButton.interactable = playerState.money >= selectedItem.price;
        }
    }

    // 타이핑 효과 코루틴
    private IEnumerator TypeWriter(string text, TextMeshProUGUI targetText)
    {
        targetText.text = "";

        foreach (char letter in text.ToCharArray())
        {
            targetText.text += letter;
            yield return new WaitForSeconds(0.05f);
        }
    }

    // 아이템 구매 처리
    private void BuyEffect()
    {
        if (selectedItem == null) return;

        State playerState = GameManager.info.allPlayerState;

        if (playerState.money >= selectedItem.price)
        {
            // 골드 차감
            playerState.money -= selectedItem.price;

            // 인벤토리에 아이템 추가
            InventoryPosition.AddItem(selectedItem);

            // 구매 효과 표시
            GameObject buyEffect = Resources.Load<GameObject>("UI/BuyEffect");
            if (buyEffect != null)
            {
                Instantiate(buyEffect, transform);
            }

            // 코인 UI 업데이트
            Inventory inventory = FindObjectOfType<Inventory>();
            if (inventory != null)
            {
                inventory.UpdateCoin();
            }

            Debug.Log($"{selectedItem.itemName}을(를) {selectedItem.price}G에 구매했습니다.");
        }
        else
        {
            Debug.Log("골드가 부족합니다!");
        }
    }
}

// 실제 EquidStoreItem.cs 코드 - 상점 아이템 컴포넌트
public class EquidStoreItem : MonoBehaviour, IPointerClickHandler
{
    [SerializeField] private Image itemIcon; // 아이템 아이콘
    [SerializeField] private TextMeshProUGUI itemNameText; // 아이템 이름
    [SerializeField] private Image backgroundImage; // 배경 이미지 (등급별 색상)

    private SelectableItem currentItem;
    private static EquidStoreItem selectedSlot; // 현재 선택된 슬롯

    public void SetItem(SelectableItem item)
    {
        currentItem = item;

        if (item != null)
        {
            itemIcon.sprite = item.itemIcon;
            itemNameText.text = item.itemName;

            // 등급별 배경 색상 설정
            Color rarityColor = GetRarityColor(item.level);
            backgroundImage.color = rarityColor;
        }
    }

    private Color GetRarityColor(EquidLevel level)
    {
        switch (level)
        {
            case EquidLevel.rare: return Color.blue;
            case EquidLevel.epic: return Color.magenta;
            case EquidLevel.unique: return Color.yellow;
            case EquidLevel.legend: return Color.red;
            default: return Color.white;
        }
    }

    public void OnPointerClick(PointerEventData eventData)
    {
        // 이전 선택 해제
        if (selectedSlot != null)
        {
            selectedSlot.SetSelected(false);
        }

        // 현재 아이템 선택
        selectedSlot = this;
        SetSelected(true);

        // 상점에 선택된 아이템 정보 전달
        EquidStore.OnSelectedItem(currentItem);
    }

    private void SetSelected(bool selected)
    {
        // 선택 상태 시각적 표시
        if (backgroundImage != null)
        {
            backgroundImage.color = selected ? Color.cyan : GetRarityColor(currentItem?.level ?? EquidLevel.rare);
        }
    }

    // 정적 메서드로 아이템 구매 (외부에서 호출)
    public static void BuyItem(SelectableItem item)
    {
        if (item == null) return;

        State playerState = GameManager.info.allPlayerState;

        if (playerState.money >= item.price)
        {
            playerState.money -= item.price;
            InventoryPosition.AddItem(item);

            Debug.Log($"{item.itemName} 구매 완료!");
        }
    }
}

// 실제 SaleItem.cs 코드 - 아이템 판매 시스템 (우클릭 판매)
public class SaleItem : MonoBehaviour, IPointerClickHandler
{
    [SerializeField] private SelectableItem currentItem; // 현재 아이템
    [SerializeField] private TextMeshProUGUI detailText; // 상세 정보 텍스트

    public void OnPointerClick(PointerEventData eventData)
    {
        if (eventData.button == PointerEventData.InputButton.Right && currentItem != null)
        {
            SellItem();
        }
        else if (eventData.button == PointerEventData.InputButton.Left)
        {
            ShowItemDetails();
        }
    }

    private void SellItem()
    {
        if (currentItem == null) return;

        // 판매 가격은 원가의 50%
        int sellPrice = Mathf.RoundToInt(currentItem.price * 0.5f);

        State playerState = GameManager.info.allPlayerState;
        playerState.money += sellPrice;

        // 인벤토리에서 아이템 제거
        InventoryPosition.RemoveItem(currentItem);

        // 코인 UI 업데이트
        Inventory inventory = FindObjectOfType<Inventory>();
        if (inventory != null)
        {
            inventory.UpdateCoin();
        }

        Debug.Log($"{currentItem.itemName}을(를) {sellPrice}G에 판매했습니다.");

        // 슬롯 비우기
        gameObject.SetActive(false);
    }

    private void ShowItemDetails()
    {
        if (currentItem == null || detailText == null) return;

        // 리플렉션을 사용하여 아이템 속성 동적 표시
        FieldInfo[] fields = currentItem.GetType().GetFields();
        string details = $"이름: {currentItem.itemName}\n";
        details += $"등급: {currentItem.level}\n";
        details += $"가격: {currentItem.price}G\n";

        foreach (FieldInfo field in fields)
        {
            if (field.FieldType == typeof(int) && field.GetValue(currentItem) != null)
            {
                int value = (int)field.GetValue(currentItem);
                if (value > 0)
                {
                    details += $"{field.Name}: +{value}\n";
                }
            }
            else if (field.FieldType == typeof(float) && field.GetValue(currentItem) != null)
            {
                float value = (float)field.GetValue(currentItem);
                if (value > 0)
                {
                    details += $"{field.Name}: +{value:F1}\n";
                }
            }
        }

        detailText.text = details;
    }
}

// EquidLevel 열거형 - 아이템 등급
public enum EquidLevel
{
    rare,    // 40% 확률
    epic,    // 30% 확률
    unique,  // 20% 확률
    legend   // 10% 확률 (상점에서 제외)
}

// SelectableItem 클래스 - 선택 가능한 아이템 데이터
[System.Serializable]
public class SelectableItem
{
    public string itemName;
    public string description;
    public Sprite itemIcon;
    public int price;
    public EquidLevel level;
    public EquipmentState equipmentType;

    // 능력치 속성들
    public int damage;
    public int defense;
    public float critical;
    public float moveSpeed;
    public int jumpPower;
}
